import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, color, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  const root = new Group();
  const timelines = [];

  const panelW = 3.4;
  const panelH = 1.9;

  // Panel with engineered gradient
  const panelGeom = new PlaneGeometry(panelW, panelH);
  const panelMat = new MeshStandardNodeMaterial();

  const uvN = uv();
  panelMat.colorNode = mix(
    color(new Color(0x111116)),
    color(new Color(0x1a1a22)),
    uvN.y
  );
  panelMat.roughness = 0.6;
  panelMat.metalness = 0.2;
  panelMat.clearcoat = 0.1;
  panelMat.transparent = true;

  const panelMesh = new Mesh(panelGeom, panelMat);
  root.add(panelMesh);

  // Quotation mark position (top-left, 0.5 unit padding)
  const qmX = -panelW / 2 + 0.5;
  const qmY = panelH / 2 - 0.5;

  // Quotation mark
  const quoteMarkObj = ctx.fontAtlas.createText('"', {
    fontSize: 62,
    color: '#ff2a38',
    align: 'left'
  });
  quoteMarkObj.position.set(qmX, qmY, 0.01);
  quoteMarkObj.scale.multiplyScalar(1.04); // Start at 1.04 for settle animation
  root.add(quoteMarkObj);

  const baseQmScale = quoteMarkObj.scale.x / 1.04;

  // Main quote (0.25 units below mark)
  const quoteObj = ctx.fontAtlas.createText(
    'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.',
    {
      fontSize: 20,
      color: '#e8ecf2',
      align: 'left',
      maxWidthPx: 240
    }
  );
  quoteObj.position.set(qmX, qmY - 0.25, 0.03); // Float +0.03 above panel
  root.add(quoteObj);

  // Accent rule (0.25 units below quote)
  const ruleGeom = new PlaneGeometry(0.2, 0.02);
  const ruleMat = new MeshStandardNodeMaterial();
  ruleMat.color.set(0xff2a38);
  ruleMat.emissive.set(0xff2a38);
  ruleMat.emissiveIntensity = 1.4;
  ruleMat.roughness = 0.6;
  ruleMat.metalness = 0.2;

  const ruleY = qmY - 0.5;
  const ruleMesh = new Mesh(ruleGeom, ruleMat);
  ruleMesh.position.set(qmX, ruleY, 0.02);
  root.add(ruleMesh);

  // Attribution
  const attrObj = ctx.fontAtlas.createText('M. OKAFOR', {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'left'
  });
  attrObj.position.set(qmX + 0.3, ruleY, 0.02);
  root.add(attrObj);

  // Caption
  const capObj = ctx.fontAtlas.createText('COLLECTOR SINCE 2019', {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'left'
  });
  capObj.position.set(qmX + 0.3, ruleY - 0.06, 0.02);
  root.add(capObj);

  // Initial state for fade-up animation
  root.position.y = 0.2;
  panelMat.opacity = 0;

  // Animation timeline
  const masterTL = gsap.timeline();
  timelines.push(masterTL);

  // Panel fade-up entrance: opacity 0->1, y +0.2->0, 500ms
  masterTL.to(root.position, {
    y: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
  }, 0);

  masterTL.to({ val: 0 }, {
    val: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    onUpdate(tween) {
      panelMat.opacity = tween.progress();
    }
  }, 0);

  // Quote mark weighted-settle: scale 1.04->1.0, 900ms, starts at 500ms
  masterTL.to(quoteMarkObj.scale, {
    x: baseQmScale,
    y: baseQmScale,
    z: 1,
    duration: 0.9,
    ease: 'cubic-bezier(0.165,0.84,0.44,1)'
  }, 0.5);

  // Cleanup function
  root.userData.cleanup = () => {
    masterTL.kill();
    panelGeom.dispose();
    panelMat.dispose();
    ruleGeom.dispose();
    ruleMat.dispose();
  };

  return root;
}
